(* [comment removed for export] *)
Definition bge_q (keli datai : Z) (rowsi : list Z) (kr datar RR : Z) (vt : pixv) (w h fr : Z) : bgk :=
  mk_bgk (p_data vt) (rsize vt) (p_wpl vt) (p_h vt) w h (fr + 144) keli datai rowsi 41 41 20 20 (fr + 80) (kr + 16) datar RR.
Definition bge_r (rf fr DD ND wpld : Z) : bgj := mk_bgj rf (fr + 128) (fr + 112) (fr + 96) (fr + 32) (fr + 48) DD ND wpld.

Section BGENV.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.

(* [comment removed for export] *)
Lemma bge_env : forall (S : rts RT) (m m' : mem) (Lr : list (Z * Z)) (rf fr keli datai : Z) (rowsi : list Z) (kr datar RR pixt : Z) (vt : pixv)
    (DD ND w h wpld : Z) (ksf rsf : Z -> Z -> Z),
  ART RT S m -> (forall e, In e Lr -> In e (rt_live RT S)) ->
  kel_obj Lr m keli 41 41 20 20 datai rowsi -> kel_obj Lr m kr 1 256 0 0 datar [RR] ->
  kel_vals m 41 rowsi ksf -> ksf 20 20 = p_one_s -> kel_vals m 256 [RR] rsf -> rsf 0 0 = p_one_s ->
  pix_obj Lr m pixt vt (mkCmapv 0 0 0 0) -> p_data vt <> 0 ->
  (forall q k x, In (q, k) Lr -> q <= x < q + k -> outside [(DD, DD + ND); (rf + 96, rf + 104); (rf + 120, rf + 128)] x) ->
  rw_cells asegs m (rf + 40) [C8 (Z_to_bv 64 wpld); C8 (Z_to_bv 64 DD); C8 (Z_to_bv 64 (fr + 128)); C8 (Z_to_bv 64 (fr + 112)); C8 (Z_to_bv 64 1)] ->
  rw_cells asegs m (rf + 88) [C8 (Z_to_bv 64 (fr + 48))] ->
  rw_cells asegs m (rf + 104) [C8 (Z_to_bv 64 (fr + 96)); C8 (Z_to_bv 64 (fr + 32))] ->
  rw_cells asegs m (fr + 32) [C4 (Z_to_bv 64 w)] -> rw_cells asegs m (fr + 48) [C4 (Z_to_bv 64 h)] ->
  rw_cells asegs m (fr + 80) [C4 (Z_to_bv 64 41)] -> rw_cells asegs m (fr + 96) [C4 (Z_to_bv 64 41)] ->
  rw_cells asegs m (fr + 112) [C4 (Z_to_bv 64 20)] -> rw_cells asegs m (fr + 128) [C4 (Z_to_bv 64 20)] ->
  rw_cells asegs m (fr + 144) [C8 (Z_to_bv 64 keli)] -> acc asegs m (fr + 144) 8 ->
  (fr + 224 <= DD \/ DD + ND <= fr) -> (fr + 224 <= rf + 96 \/ rf + 128 <= fr) -> (rf + 128 <= DD \/ DD + ND <= rf) ->
  (DD + ND <= 0x7fff8000 \/ 0x10007fff8000 <= DD) -> (rf + 128 <= 0x7fff8000 \/ 0x10007fff8000 <= rf) -> 0 <= fr -> fr + 224 <= 2^47 ->
  munch (bge_Wi (bge_r rf fr DD ND wpld)) m m' -> wmono asegs m m' ->
  bgk_ro (bge_q keli datai rowsi kr datar RR vt w h fr) ksf (rsf 0) m' /\ bgf_ro (bge_q keli datai rowsi kr datar RR vt w h fr) (bge_r rf fr DD ND wpld) m'.
Proof using AF GP.
