(* [comment removed for export] *)
Lemma bge_ok : forall (S : rts RT) (m : mem) (Lr : list (Z * Z)) (rf fr keli datai : Z) (rowsi : list Z) (kr datar RR pixt : Z) (vt : pixv)
    (pixd : Z) (vd v : pixv),
  ART RT S m -> (forall e, In e Lr -> In e (rt_live RT S)) ->
  kel_obj Lr m keli 41 41 20 20 datai rowsi -> kel_obj Lr m kr 1 256 0 0 datar [RR] ->
  pix_obj Lr m pixt vt (mkCmapv 0 0 0 0) -> p_data vt <> 0 -> p_d vt = 8 ->
  pix_obj (rt_live RT S) m pixd vd (mkCmapv 0 0 0 0) -> p_data vd <> 0 -> p_d vd = 8 ->
  pix_hdr_ok v -> p_w vt = p_w v + 20 + 21 -> p_h vt = p_h v + 20 + 21 -> p_w vd = p_w v -> p_h vd = p_h v ->
  arange rf 128 -> rf mod 8 = 0 -> arange fr 224 -> fr mod 32 = 0 ->
  (p_data vd + rsize vd <= rf \/ rf + 128 <= p_data vd) ->
  bgk_ok (bge_q keli datai rowsi kr datar RR vt (p_w v) (p_h v) fr) /\ bgj_ok (bge_q keli datai rowsi kr datar RR vt (p_w v) (p_h v) fr) (bge_r rf fr (p_data vd) (rsize vd) (p_wpl vd)).
